# -*- coding: utf-8 -*-
"""Canonical-value rulings for every contested quantity (2026-08 review).

The peer-review register (docs/PEER_REVIEW_MASTER_LIST.md, section C-1)
found the paper publishing multiple incompatible values for ~20 headline
quantities. This module is the single ruling table that resolves each
conflict, chosen under the project's stated principle:

    prefer the geometrically minimal resolution — the candidate derived
    from the seed (b3, b2) of the path in force plus already-present
    structural integers, with the fewest spare variables — unless the data
    have falsified it, in which case keep the elegant candidate on the
    books as FALSIFIED rather than silently swapping it out.

Every entry records the canonical value, its derivation arity
(``spare_vars`` = inputs beyond {b3, structural integers}), the empirical
comparison, and the superseded candidates with the reason each was retired.
``generate_canonical_values`` emits this as AutoGenerated/canonical_values.json
so prose, drift auditors, and future templating read ONE source.

PATH DEPENDENCE (2026-11-11). The table used to be written at b3 = 24,
b2 = 4, chi_eff = 6 b3 = 144 -- the retired seed_24 -- while the adopted
seed is seed_43_joyce. ``B3``, ``B2``, ``CHI_EFF``, ``CHI_SECTOR`` and
``CANON`` are now computed at access from ``active_path.topology()``
(module ``__getattr__``, PEP 562), and ``canon(path)`` builds the table for
any path. Entries that depend on the seed (w0, wa, H0, alpha_leak) state
their form and numbers from the computed values and keep the seed_24
reading as a labelled retired row in ``superseded``. H0 and tau_p are
computed quantities, never typed. H0 is computed at access by
``FormulasRegistry.calculate_h0_local`` and is NOT_EVALUABLE on a path that
is not the path in force; its form, status and note are those of the
``h0_route`` in force (``late_time_routes.resolve_h0_route``), since the
method returns another route's value when the fork is not on the adopted
option. tau_p is read from the parameter artifact in the
output directory: NOT_EVALUABLE (value None) when there is no artifact or
it was built on another (b3, b2); an artifact that lacks the row raises.
"""
from __future__ import annotations

import copy
import math
from typing import Any, Callable, Dict, Optional

from metaphysica.simulations.core.active_path import Topology, topology

#: The retired seed whose values the table used to be written at.
_RETIRED_SEED = "seed_24"


def _retired_key(value: float) -> str:
    """A superseded key for the seed_24 reading of an entry.

    The key starts with the seed name, not a number, so the reading is
    labelled as a retired path rather than as a competing candidate value.
    """
    return "%s reading %.6g" % (_RETIRED_SEED, value)


def _de_betti_n(topo: Topology) -> "tuple[str, int]":
    """(option, n) of the dark_energy_betti fork on *topo*'s path."""
    from metaphysica.simulations.PM.cosmology.late_time_routes import (
        de_betti_n,
        resolve_de_betti,
    )

    option = resolve_de_betti()
    n = topo.b3 if option == "b3_live" else de_betti_n(option)
    return option, int(n)


def _w0_entry(topo: Topology) -> Dict[str, Any]:
    option, n = _de_betti_n(topo)
    value = -(n - 1) / n
    frozen = option != "b3_live"
    entry: Dict[str, Any] = {
        "value": value,
        "form": "-(n-1)/n with n = %d (dark_energy_betti = %s) = %d/%d"
                % (n, option, -(n - 1), n),
        "status": "INPUT" if frozen else "PREDICTED",
        "spare_vars": 1 if frozen else 0,
        "comparison": {"dataset": "DESI thawing anchor", "exp": -0.957, "unc": 0.067},
        "superseded": {
            "-0.8528": "thermal-time alpha_T=4.5 mechanism (retired pre-DESI candidate)",
            "-0.980": "a z-evolution output misquoted as w0",
            "-1.0": "the LambdaCDM limit, not a framework value",
            _retired_key(-23 / 24): "-(b3-1)/b3 at the retired seed b3 = 24",
        },
    }
    if frozen:
        entry["note"] = (
            "n = %d is a frozen integer set by the dark_energy_betti option "
            "%s, not the live b3 = %d; w0 is therefore an input constant and "
            "is not scored as a prediction. Under dark_energy_betti = b3_live "
            "it would be -(b3-1)/b3 = %.6g." % (n, option, topo.b3,
                                                -(topo.b3 - 1) / topo.b3))
    return entry


def _sigma(value: float, exp: float, unc: float) -> float:
    return abs(value - exp) / unc


#: dim(Psi) = 4: the co-associative 4-form multiplier of the registered
#: variant cosmology.wa_projection_x4 (GeometricAnchors.wa_projection_x4 =
#: 4 wa). It is the form degree, not b2, and does not change with the path.
_WA_PROJECTION_DIM_PSI = 4


def _wa_entry(topo: Topology) -> Dict[str, Any]:
    value = -1.0 / math.sqrt(topo.b3)
    projection = _WA_PROJECTION_DIM_PSI * value
    exp, unc = -0.75, 0.29
    sigma, sigma_projection = _sigma(value, exp, unc), _sigma(projection, exp, unc)
    retired_value = -1.0 / math.sqrt(24)
    return {
        "value": value,
        "form": "-1/sqrt(b3), b3 = %d" % topo.b3,
        "status": "PREDICTED",
        "spare_vars": 0,
        "comparison": {"dataset": "DESI DR1 w0waCDM", "exp": exp, "unc": unc,
                       "sigma": sigma},
        "note": (
            "Ruling: the pure form is canonical, %.2f sigma from DESI DR1 at "
            "b3 = %d, although the x dim(Psi) = 4 projection (%.4f) sits at "
            "%.2f sigma: the multiplier was introduced after DESI and is "
            "exactly the 'spare variable' the elegance principle excludes. "
            "The projection stays registered as cosmology.wa_projection_x4, "
            "status RETRODICTED."
            % (sigma, topo.b3, projection, sigma_projection)),
        "superseded": {
            "%.4f" % projection: "x dim(Psi) = 4 projection (cosmology.wa_projection_x4), "
                                 "post-DESI graft -> kept as RETRODICTED variant",
            "+0.27": "thermal alpha_T form (wrong sign vs data)",
            "+0.1": "attractor estimate (wrong sign vs data)",
            "+0.29": "sign-error copy of 1/sqrt(12)",
            _retired_key(retired_value): "-1/sqrt(b3) at the retired seed b3 = 24",
            _retired_key(_WA_PROJECTION_DIM_PSI * retired_value):
                "x dim(Psi) = 4 projection -4/sqrt(b3) at the retired seed b3 = 24",
        },
    }


def _unevaluated(source: str, note: str) -> Dict[str, Any]:
    """A NOT_EVALUABLE entry: no value, with the reason in *note*."""
    return {
        "value": None,
        "status": "NOT_EVALUABLE",
        "spare_vars": None,
        "comparison": None,
        "source": source,
        "note": note,
        "superseded": {},
    }


def _output_artifact() -> Optional[Dict[str, Any]]:
    """The rows of the parameter artifact in the output directory, or None.

    Only the output directory (``METAPHYSICA_OUT``, else the working
    directory) is read: an artifact elsewhere was built by another build.
    An artifact that exists but cannot be read, or has no rows, raises
    with the path of the file in the message.
    """
    import json

    from metaphysica.generators._common import out_dir

    path = out_dir() / "AutoGenerated" / "parameters.json"
    if not path.is_file():
        return None
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except ValueError as exc:  # JSONDecodeError and UnicodeDecodeError
        raise ValueError("%s is not valid JSON: %s" % (path, exc)) from exc
    rows = payload.get("parameters") if isinstance(payload, dict) else None
    if not isinstance(rows, dict) or not rows:
        raise ValueError("%s has no 'parameters' rows" % path)
    return rows


def _artifact_value(row: str, rows: Dict[str, Any]) -> float:
    """The parameter artifact's value of *row*; raises when it is absent.

    A computed quantity is never typed into CANON: it is read from the
    artifact the build wrote (the path the artifact was built on).
    """
    from metaphysica.simulations.core.parameter_artifact import parameter_value

    value = parameter_value(row, rows)
    if value is None:
        raise KeyError(
            "%s is not in the parameter artifact; it is a computed quantity "
            "and is never typed into CANON (build the artifact first)" % row)
    return value


#: Artifact rows that record the seed the artifact was built on.
_ARTIFACT_SEED_ROWS = ("topology.elder_kads", "topology.b2")


def _artifact_seed(rows: Dict[str, Any]) -> "tuple[int, int]":
    """(b3, b2) of the path the parameter artifact was built on; raises when absent."""
    b3, b2 = (_artifact_value(row, rows) for row in _ARTIFACT_SEED_ROWS)
    return int(b3), int(b2)


def _not_evaluable(row: str, topo: Topology,
                   rows: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """A NOT_EVALUABLE entry when there is no artifact or it was built on
    another seed, else None.

    The artifact holds one build. Read on a path whose (b3, b2) differ from
    the build's, its value would answer for a path it was not computed on.
    """
    source = "parameter artifact row %s" % row
    if rows is None:
        return _unevaluated(source, "no parameter artifact in the output directory")
    built = _artifact_seed(rows)
    if built == (topo.b3, topo.b2):
        return None
    return _unevaluated(source, (
        "%s is a computed quantity read from the parameter artifact, "
        "which was built at (b3, b2) = %s; path %r has (b3, b2) = "
        "(%d, %d), so it is not evaluated here (rebuild the artifact "
        "on that path)." % (row, built, topo.path, topo.b3, topo.b2)))


def _h0_off_path(topo: Topology) -> Optional[Dict[str, Any]]:
    """NOT_EVALUABLE when *topo* is not the path in force, else None.

    H0 is computed by ``FormulasRegistry.calculate_h0_local``, which reads
    the path in force only; it has no value for another path.
    """
    live = topology()
    if (live.b3, live.b2) == (topo.b3, topo.b2):
        return None
    return _unevaluated("FormulasRegistry.calculate_h0_local", (
        "H0 is computed by FormulasRegistry.calculate_h0_local on the path "
        "in force only; the path in force %r has (b3, b2) = (%d, %d) and "
        "path %r has (b3, b2) = (%d, %d), so it is not evaluated here."
        % (live.path, live.b3, live.b2, topo.path, topo.b3, topo.b2)))


#: H0 comparison data (value, 1 sigma) in km/s/Mpc: SH0ES 2022, Planck 2018.
_H0_SHOES = (73.04, 1.04)
_H0_PLANCK = (67.4, 0.5)

#: The method that computes H0 under every option of the h0_route fork.
_H0_METHOD = "FormulasRegistry.calculate_h0_local"


def _h0_odowd(registry: Any, b3: int, value: float) -> Dict[str, Any]:
    """Form, status and arity of h0_route odowd_composite (the adopted route).

    eta_S is printed from ``BULK_PRESSURE``, the constant the registry
    divides by (10 b3 - 1) to get it.
    """
    return {
        "form": ("O'Dowd composite: %d/4 - (7 b3 - 5)/(b3^2/4) + eta_S, "
                 "eta_S = %d/(10 b3 - 1), b3 = %d, computed by %s"
                 % (registry.roots_total, registry.BULK_PRESSURE, b3, _H0_METHOD)),
        "status": "FITTED_COMPOSITE",
        "spare_vars": 3,
        "what": "the O'Dowd composite (3 fitted inputs)",
    }


def _h0_ricci_flow(registry: Any, b3: int, value: float) -> Dict[str, Any]:
    """Form, status and arity of h0_route ricci_flow.

    The mixing angle is fitted and H0_planck is a measured input, so the
    route carries the status of its registry row cosmology.H0_ricci_variant.
    """
    from metaphysica.simulations.PM.cosmology.ricci_flow_h0 import (
        THETA_MIXING_13D_26D_DEG,
    )

    return {
        "form": ("Ricci-flow route: H0_planck (1 + sin^2(theta)/2), theta = "
                 "%g deg (fitted 13D/26D mixing angle), H0_planck = %g "
                 "(Planck 2018, a measured input), computed by %s under "
                 "h0_route = ricci_flow"
                 % (THETA_MIXING_13D_26D_DEG, registry.h0_early, _H0_METHOD)),
        "status": "RETRODICTED_VARIANT",
        "spare_vars": 2,
        "what": "the ricci-flow variant (a fitted angle on the Planck input)",
    }


