#: Builder of the form, status and arity of each option of the h0_route fork.
_H0_ROUTES: Dict[str, Callable[[Any, int, float], Dict[str, Any]]] = {
    "odowd_composite": _h0_odowd,
    "ricci_flow": _h0_ricci_flow,
    "kk_bridge": _h0_kk_bridge,
}


def _h0_note(route: str, adopted: str, what: str, value: float) -> str:
    """The ruling note of the H0 entry under *route* of the h0_route fork."""
    sigmas = (_sigma(value, *_H0_SHOES), _sigma(value, *_H0_PLANCK))
    if route == adopted:
        return (
            "Ruling: H0 is NOT a topology-first prediction in the current "
            "framework. The minimal candidate (Planck x golden-angle "
            "correction, 1 var) lands 3.5 sigma from SH0ES and 18.6 from "
            "Planck — dead. The O'Dowd composite (3 fitted inputs, %.2f "
            "sigma SH0ES / %.1f Planck) is the canonical DISPLAY value; the "
            "ricci-flow variant is registered separately as "
            "cosmology.H0_ricci_variant and all 'Hubble tension resolved' "
            "claims are retired." % sigmas)
    return (
        "Ruling: H0 is NOT a topology-first prediction in the current "
        "framework. The h0_route fork resolves to %r, not the adopted route "
        "%r: this entry is %s, %.2f sigma SH0ES / %.1f Planck, and NOT the "
        "canonical DISPLAY value, which is the O'Dowd composite of the "
        "adopted route. The rows in 'superseded' are the ruling's record "
        "under the adopted route, and all 'Hubble tension resolved' claims "
        "are retired." % ((route, adopted, what) + sigmas))


def _h0_route_text(registry: Any, topo: Topology) -> Dict[str, Any]:
    """Value, form, status, arity, source and note under the h0_route in force.

    *registry* is the one instance of the entry: it computes the value and
    supplies the numbers the form prints. A route with no builder raises.
    """
    from metaphysica.simulations.PM.cosmology import late_time_routes as ltr

    if registry.elder_kads != topo.b3:
        raise ValueError(
            "the registry seed b3 = %r is not the b3 = %r of path %r; H0 is "
            "computed on the path in force only"
            % (registry.elder_kads, topo.b3, topo.path))
    route, adopted = ltr.resolve_h0_route(), ltr.ADOPTED_H0_ROUTE
    if route not in _H0_ROUTES:
        raise ValueError("h0_route %r has no CANON form and status" % route)
    value = registry.calculate_h0_local()
    text = _H0_ROUTES[route](registry, topo.b3, value)
    source = "%s on the path in force" % _H0_METHOD
    if route != adopted:
        source += ", h0_route = %s" % route
    return {
        "value": value,
        "form": text["form"],
        "status": text["status"],
        "spare_vars": text["spare_vars"],
        "source": source,
        "note": _h0_note(route, adopted, text["what"], value),
    }


def _h0_entry(topo: Topology) -> Dict[str, Any]:
    """The H0 entry: value, form and status of the h0_route in force."""
    unevaluated = _h0_off_path(topo)
    if unevaluated is not None:
        return unevaluated
    from metaphysica.simulations.core.FormulasRegistry import FormulasRegistry

    text = _h0_route_text(FormulasRegistry(), topo)
    return {
        "value": text["value"],
        "form": text["form"],
        "status": text["status"],
        "spare_vars": text["spare_vars"],
        "comparison": {"dataset": "SH0ES 2022", "exp": _H0_SHOES[0],
                       "unc": _H0_SHOES[1]},
        "source": text["source"],
        "note": text["note"],
        "superseded": {
            "76.34": "ricci-flow variant (3.17 sigma SH0ES) -> cosmology.H0_ricci_variant",
            "70.42": "sterile extraction (2.5 sigma SH0ES, 6.0 Planck)",
            _retired_key(71.55): "288/4 - 163/144 + 0.6819 at the retired seed b3 = 24",
        },
    }


def _tau_p_entry(topo: Topology) -> Dict[str, Any]:
    row = "proton_decay.tau_p_years"
    rows = _output_artifact()
    unevaluated = _not_evaluable(row, topo, rows)
    if unevaluated is not None:
        return unevaluated
    value = _artifact_value(row, rows)
    bound = 2.4e34
    return {
        "value": value,
        "form": "registry proton_decay chain, read from %s" % row,
        "status": "PREDICTED",
        "spare_vars": 2,
        "comparison": {"dataset": "Super-K p->e+pi0 bound (PDG 2024)", "exp": bound, "unc": None,
                        "kind": "lower_bound", "ratio": value / bound},
        "source": "parameter artifact row %s (the path the artifact was built on)" % row,
        "superseded": {
            "3.9e34": "prose rounding drift",
            "8.15e34": "stale config literal",
            "1.0e34": "wrong output binding",
        },
    }


def _alpha_leak_entry(topo: Topology) -> Dict[str, Any]:
    ratio = topo.chi_eff / topo.b3
    return {
        "value": 1.0 / math.sqrt(ratio),
        "form": "1/sqrt(chi_eff/b3) = 1/sqrt(%d/%d)" % (topo.chi_eff, topo.b3),
        "status": "DERIVED",
        "spare_vars": 0,
        "comparison": None,
        "note": (
            "Naming ruling: only 1/sqrt(chi_eff/b3) is alpha_leak. 0.57 is "
            "alpha_sample (ANSATZ, four_face); 1/(4pi)-family factors are "
            "alpha_moduli (PHENOMENOLOGICAL); the per-force table values "
            "are alpha_leak_i couplings. The four were sharing one symbol."
        ),
        "superseded": {
            "0.57": "alpha_sample ANSATZ mis-labelled as alpha_leak",
            "0.0796": "moduli loop factor 1/(4pi), different quantity",
            _retired_key(1.0 / math.sqrt(6.0)): "1/sqrt(144/24) at the retired seed b3 = 24",
        },
    }


