def _entry(symbol: str, topo: Topology) -> Dict[str, Any]:
    """One entry of the ruling table on *topo*'s path."""
    builder = _PATH_ENTRIES.get(symbol)
    if builder is not None:
        return builder(topo)
    return copy.deepcopy(_STATIC[symbol])


def canon(path: Optional[str] = None) -> Dict[str, Dict[str, Any]]:
    """The ruling table on *path* (the path in force when None)."""
    topo = topology(path)
    return {symbol: _entry(symbol, topo) for symbol in _ORDER}


def get(symbol: str) -> Dict[str, Any]:
    """The entry for *symbol* on the path in force; builds that entry only."""
    if symbol not in _ORDER:
        raise KeyError("%r is not a canonical symbol" % symbol)
    return _entry(symbol, topology())


def all_canonical() -> Dict[str, Dict[str, Any]]:
    return canon()


#: Module attributes computed at access from the path in force (PEP 562).
_TOPOLOGY_NAMES: Dict[str, Callable[[Topology], int]] = {
    "B3": lambda t: t.b3,
    "B2": lambda t: t.b2,
    "CHI_EFF": lambda t: t.chi_eff,
    "CHI_SECTOR": lambda t: t.chi_sector,
}


def __getattr__(name: str) -> Any:
    if name in _TOPOLOGY_NAMES:
        return _TOPOLOGY_NAMES[name](topology())
    if name == "CANON":
        return canon()
    raise AttributeError("module %r has no attribute %r" % (__name__, name))
